import{bV as a,aL as t,u as r,G as i}from"./chunks/framework.DvBUyM1S.js";const f=JSON.parse('{"title":"慎用Number.toFixed()","description":"","frontmatter":{"title":"慎用Number.toFixed()","date":"2021-7-28","tags":["JavaScript"],"permalink":"/pages/db36f6/","categories":["前端","JavaScript"]},"headers":[],"relativePath":"02.开发/06.JavaScript/02.慎用NumbertoFixed.md","filePath":"02.开发/06.JavaScript/02.慎用NumbertoFixed.md","lastUpdated":1652078909000}'),o={name:"02.开发/06.JavaScript/02.慎用NumbertoFixed.md"};function p(n,e,l,d,c,b){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="慎用number-tofixed" tabindex="-1">慎用Number.toFixed() <a class="header-anchor" href="#慎用number-tofixed" aria-label="Permalink to &quot;慎用Number.toFixed()&quot;">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>最近在公司项目中碰到一个隐藏的 bug，调试许久才发现竟然是 toFixed 函数精度问题引起的，从而引发了我一系列的思考。</p><p>我们都知道，计算机在二进制环境下，浮点数的计算精度会存在缺失问题，最经典的例子就是为什么 0.1+0.2 不等于 0.3？</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/be8ec0c6599d4bb8b950568b0613f5be~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>为了解决上述问题，我们自然而然会想到 toFixed 方法来四舍五入，可结果却不如人意！</p><h2 id="tofixed-的精度问题" tabindex="-1">toFixed()的精度问题 <a class="header-anchor" href="#tofixed-的精度问题" aria-label="Permalink to &quot;toFixed()的精度问题&quot;">​</a></h2><p>我们来看一下 toFixed()在 chrome、火狐、IE 浏览器下的不同表现：</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/cc2b27176ba147aab00d333b854b5ed3~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>可以看到 toFixed()的四舍五入在 chrome、火狐上并不准确。 而 toFixed()在 chrome、火狐上也并不是网上流传甚广的用银行家舍入法来进行四舍五入的。</p><blockquote><p>银行家舍入法的规则是“四舍六入五考虑，五后非零就进一，五后为零看奇偶，五前为偶应舍去，五前为奇要进一”。</p></blockquote><p>例如银行家舍入法在 (2.55).toFixed(1) = 2.5、(3.55).toFixed(1) = 3.5 上就不符合了。</p><p>翻阅<a href="https://262.ecma-international.org/6.0/#sec-number.prototype.tofixed" target="_blank" rel="noreferrer">ecmascript 规范</a>对 toFixed 的表述如下：</p><p><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/56fb7cd1c40b4d4b9c08ef3f463d4639~tplv-k3u1fbpfcp-watermark.image" alt="Number.prototype.toFixed" loading="lazy"></p><p>上面规范这段大概意思就是如果 toFixed 的入参小于 10 的 21 次方，那么就取一个整数 n，让 n*10^f - x 的精确值尽可能的趋近于 0，如果存在两个这样的 n,取较大的 n。这段话可能有点晦涩难懂，我们举个例子比如 1.335.toFixed(2)</p><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/8c8e3040ae7644faa5ec7b4ef82377d2~tplv-k3u1fbpfcp-watermark.image" alt="image.png" loading="lazy"></p><p>上图例子中 1.335.toFixed(2)按照四舍六入五成双应该是 1.34，但是实际情况确实 1.33。这是因为 n=133 的时候让 n*10^f - x 更趋近于 0，所以最后得到的结果是 1.33。</p><h2 id="解决方法" tabindex="-1">解决方法 <a class="header-anchor" href="#解决方法" aria-label="Permalink to &quot;解决方法&quot;">​</a></h2><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="https://juejin.cn/post/6927215610552123406" target="_blank" rel="noreferrer">toFixed 四舍五入的不准确性</a></li><li><a href="https://www.daimajiaoliu.com/daima/479775a03100402" target="_blank" rel="noreferrer">JS toFixed 及其缺陷和解决方法</a></li><li><a href="http://www.chengfeilong.com/toFixed" target="_blank" rel="noreferrer">toFixed 计算错误解决方法</a></li><li><a href="https://www.iwangzhu.top/article/14" target="_blank" rel="noreferrer">那些年在 JS 中踩过 Number.toFixed(n)的坑</a></li><li><a href="https://juejin.cn/post/6844903703565041678" target="_blank" rel="noreferrer">JS 四则运算与四舍五入精度问题及解决方案</a></li></ul>',20)])])}const s=a(o,[["render",p]]);export{f as __pageData,s as default};
